  const it = msg.interactive || {};
  text = (it.list_reply && it.list_reply.title) || (it.button_reply && it.button_reply.title) || '';
  replyId = (it.list_reply && it.list_reply.id) || (it.button_reply && it.button_reply.id) || '';
} else if (type === 'button') {
  text = (msg.button && msg.button.text) || '';
  replyId = (msg.button && msg.button.payload) || '';
} else if (type === 'image' || type === 'video' || type === 'document') text = (msg[type] && msg[type].caption) || '';
text = String(text).trim();

const isAdmin = from === ADMIN;
let adminCmd = '';
let adminTarget = '';
if (isAdmin) {
  const cm = text.match(/^\s*(pause|stop|resume|start|status)\b[\s:]*\+?(\d[\d\s-]{8,})/i);
  if (cm) {
    adminCmd = cm[1].toLowerCase();
    adminCmd = ({ stop: 'pause', start: 'resume' })[adminCmd] || adminCmd;
    adminTarget = cm[2].replace(/\D/g, '');
    if (adminTarget.length === 10) adminTarget = '91' + adminTarget;
  }
}

return [{ json: {
  from: from,
  msg_id: msg.id || '',
  type: type,
  text: text,
  reply_id: replyId,
  context_id: (msg.context && msg.context.id) || '', // the message Mahek swipe-replied to
  is_admin: isAdmin,
  admin_cmd: adminCmd,
  lookup_phone: adminTarget || from,
  contact_name: (trig.contacts && trig.contacts[0] && trig.contacts[0].profile && trig.contacts[0].profile.name) || '',
  phone_number_id: (trig.metadata && trig.metadata.phone_number_id) || '',
  received_ms: Date.now(),
