  if (type === 'text' && !isGreeting && !isFiller) rec.interested_items = appendItems(rec.interested_items, 'First message: ' + text);
  if (itemAsk && !humanStrong) { lang = scriptLang || 'en'; route = 'resend_rates'; quickStart = 'details'; newStage = 'awaiting_details'; }
  else if (scriptLang) { lang = scriptLang; route = 'greet'; newStage = 'awaiting_details'; }
  else { route = 'ask_language'; newStage = 'awaiting_language'; }
} else if (stage === 'awaiting_language') {
  const l = text.toLowerCase();
  if (itemAsk && !replyId && !humanStrong) {
    // asked about items instead of picking a language: answer, and carry on in English (or the script they wrote in)
    rec.interested_items = appendItems(rec.interested_items, text);
    lang = scriptLang || (typedLang ? LANG_WORDS[typedLang] : 'en'); route = 'resend_rates'; quickStart = 'details'; newStage = 'awaiting_details';
  }
  // typed instead of tapped, with typos: "hindhi", "englis", "tamizh", "telgu" – or written in that script
  else if (!replyId && (typedLang || scriptLang)) { lang = typedLang ? LANG_WORDS[typedLang] : scriptLang; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_gu' || /gujarati|gujrati|ગુજરાતી/.test(l)) { lang = 'gu'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_hi' || /hindi|हिंदी|हिन्दी/.test(l)) { lang = 'hi'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_ta' || /tamil|தமிழ்/.test(l)) { lang = 'ta'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_te' || /telugu|తెలుగు/.test(l)) { lang = 'te'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_en' || /english|इंग्लिश|अंग्रेज़ी|अंग्रेजी/.test(l)) { lang = 'en'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (humanStrong) startHandoff('Asked to speak to a sales associate / human');
  else if (isGreeting && tries < 1) retryOrHandoff('ask_language'); // a second "hi": show the language list once more
  else { lang = 'en'; route = 'greet'; newStage = 'awaiting_details'; } // anything else: carry on in English
} else if (langPick) {
  // changed language later (tapped an old language list, or typed "Hindi"): switch and repeat the current step
  lang = langPick; langChanged = true;
  if (stage === 'awaiting_details') route = 'greet';
  else if (stage === 'awaiting_category') route = 'ask_category';
  else if (afterCatalogue) route = 'resend_rates';
  else route = 'greet';
} else if (typedOrder && afterCatalogue && !humanStrong) {
  // an order typed in the chat: rate list opened on those items so they can send it properly, and Mahek is told
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
  alertTitle = 'Customer typed an order in the chat (' + askCodes.join(', ') + '). The bot sent the rate list with these items – please check.';
  rec.last_alert_at = now;
} else if (type === 'interactive' && TYPE_IDS[replyId] && afterCatalogue) {
  // Tapped the business-type list again later: switch the type and resend the rate list link.
  rec.category = TYPE_NAMES[TYPE_IDS[replyId]];
  route = 'resend_rates';
  newStage = 'rate_list_sent';
} else if (afterCatalogue && !humanStrong && (priceAsk || askCodes.length)) {
  // "item 345 price?", "hair bows rate?" after the rate list: send the rate list link again (opened on that item)
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
} else if (afterCatalogue && !humanStrong && !availAsk && (catalogueAsk || productAsk)) {
  // "scrunchies designs?", "catlog" – send the catalogue links again
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_catalogue';
} else if (((stage === 'awaiting_details' && detailsAsk) || (stage === 'awaiting_category' && !categoryHit && itemAsk)) && !humanStrong) {
  // A price / item question while we wait for the shop name / business type: send the rate list now, and ask again in the same message.
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
  quickStart = stage === 'awaiting_details' ? 'details' : 'type';
} else if ((stage === 'awaiting_details' || (stage === 'awaiting_category' && !categoryHit)) && type === 'text' && !humanStrong &&
    (availAsk || /\?/.test(text))) {
  // Another question while we wait: note it and ask again.
  rec.interested_items = appendItems(rec.interested_items, text);
  retryOrHandoff(stage === 'awaiting_details' ? 'details_retry' : 'ask_category');
} else if (afterCatalogue && wantsCatalogue) {
  route = 'resend_catalogue';
} else if (stage === 'rate_list_sent' && wantsRates) {
  route = 'resend_rates';
} else if (flowFinished && isGreeting) {
  // returning customer says hi: welcome them back with their rate list button instead of starting over
  route = 'resend_rates';
  welcomeBack = true;
} else if (wantsHuman) {
  if (afterCatalogue) rec.interested_items = appendItems(rec.interested_items, text);
  startHandoff('Asked to speak to a sales associate / human');
} else if (stage !== 'escalated_to_sales' && wantsInfo && !(stage === 'awaiting_category' && categoryHit)) {
  if (afterCatalogue) rec.interested_items = appendItems(rec.interested_items, text);
  startHandoff('Needs more information');
} else if (stage === 'awaiting_details') {
  const fillers = ['hi', 'hii', 'hiii', 'hello', 'helo', 'hey', 'namaste', 'ok', 'okay', 'k', 'yes', 'no', 'thanks', 'thank you', 'thankyou', 'good morning', 'good afternoon', 'good evening', 'catalogue', 'catalog', 'price', 'rate', 'rates'];
  const c2 = lower.replace(/[^a-zऀ-ॿ઀-૿஀-௿ఀ-౿ ]/g, '').trim();
  const valid = type === 'text' && c2.length >= 3 && !fillers.includes(c2) && !FILLERS.includes(c2);
  if (valid) {
    route = 'ask_category';
    rec.business_details = text;
    newStage = 'awaiting_category';
  } else {
    retryOrHandoff('details_retry');
  }
} else if (stage === 'awaiting_category') {
  // List ids, or a typed answer matched by keyword. Old list ids (shopkeeper, new_business) still work.
  const hit = categoryHit;
  if (hit || type === 'interactive') {
    // Catalogue links + rate list link go out together; no order-value question any more.
    route = 'send_catalogue';
    rec.category = hit ? TYPE_NAMES[hit] : (text || 'Other / Home seller');
    newStage = 'rate_list_sent';
  } else {
    retryOrHandoff('ask_category');
  }
} else if (stage === 'awaiting_order_value') {
  const lowSel = replyId === 'ov_low' || /less than|से कम|கீழ்|కంటే తక్కువ/i.test(text);
  const highSel = replyId === 'ov_high' || /or more|या अधिक|से ज़्यादा|से ज्यादा|அல்லது மேல்|లేదా ఎక్కువ/i.test(text);
  const typed = (lowSel || highSel) ? null : parseAmount(text);
  const amt = highSel ? BIG_ORDER : (lowSel ? 0 : typed);
  if (amt === null) {
    rec.interested_items = appendItems(rec.interested_items, text);
    retryOrHandoff('order_retry');
  } else if (amt < BIG_ORDER) {
    route = 'order_low';
    rec.order_value = lowSel ? 'Less than ₹10,000' : inr(amt);
    belowMoq = !lowSel && amt < MOQ;
    newStage = 'rate_list_sent';
  } else {
    route = 'order_high';
    rec.order_value = highSel ? '₹10,000 or more' : inr(amt);
    newStage = 'escalated_to_sales';
    alertTitle = 'Big order (₹10,000 or more). Please contact this customer.';
    rec.last_alert_at = now;
    rec.paused_until = nowDt.plus({ hours: HANDOFF_PAUSE_HOURS }).toFormat(FMT);
  }
} else if (!isFiller) {
  rec.interested_items = appendItems(rec.interested_items, text);
  if (stage === 'rate_list_sent') startHandoff('Sent items / follow-up after receiving the rate list');
  else if (stage === 'escalated_to_sales') startHandoff('Follow-up message after a big-order request');
  else if (stage === 'order_received') startHandoff('Follow-up message after a website order');
  else startHandoff('Sent a message the bot could not handle');
}

