// "Hindi", "tamil please" typed later, or a tap on an old language list
const LANG_WORDS = { gujarati: 'gu', gujrati: 'gu', gujarathi: 'gu', gujraati: 'gu', gujju: 'gu', 'ગુજરાતી': 'gu', hindi: 'hi', hindhi: 'hi', hinglish: 'hi', english: 'en', angrezi: 'en', tamil: 'ta', tamizh: 'ta', thamizh: 'ta', telugu: 'te', telgu: 'te', thelugu: 'te' };
const typedLang = tokens.map((w) => (LANG_WORDS[w] ? w : Object.keys(LANG_WORDS).find((v) => near(w, v)))).find(Boolean); // exact word first: "english" is also 2 typos from "hinglish"
const langPick = ({ lang_en: 'en', lang_hi: 'hi', lang_gu: 'gu', lang_ta: 'ta', lang_te: 'te' })[replyId] || (type === 'text' && typedLang && tokens.every((w) => Object.keys(LANG_WORDS).some((v) => near(w, v)) || ['please', 'pls', 'plz', 'in', 'language', 'me', 'mein', 'main', 'bhasha', 'bhasa', 'reply', 'talk', 'chahiye', 'ok'].includes(w)) ? LANG_WORDS[typedLang] : '');
const itemAsk = type === 'text' && (priceAsk || askCodes.length > 0 || catalogueAsk || productAsk);
// While we wait for the shop name, only a clear price question or item code counts: shop names often contain product
// words ("Krishna Hair Bows, Indore"), and "Name, City" is the answer we asked for.
const detailsAsk = type === 'text' && (priceAsk || askCodes.length > 0) && !(/[,\n]/.test(text) && !text.includes('?') && !askCodes.length);
const categoryHit = TYPE_IDS[replyId] || (TYPE_KW.find(([re]) => re.test(text)) || [])[1] || '';
// A message written in Hindi, Gujarati, Tamil or Telugu script tells us the language straight away.
const scriptLang = /[ઁ-૿]/.test(text) ? 'gu' : /[ऀ-ॿ]/.test(text) ? 'hi' : /[஀-௿]/.test(text) ? 'ta' : /[ఀ-౿]/.test(text) ? 'te' : '';

// "Strong" phrases clearly ask for a person. Single words like "sales" / "owner" / "phone"
// also count after the details step, but NOT while we are waiting for the shop name,
// because names like "Krishna Sales, Indore" contain them.
const humanStrong = /\b(talk|speak|chat)\s+(to|with)\b|\b(call me|call back|callback|call karo|call kijiye|phone karo|contact me)\b|\b(human|real person|live agent|customer care|customer support|representative)\b|\bsales\s*(person|team|associate|executive|rep|manager)\b|\bbaat\s*kar|\bva+t\s*kar(vi|o|jo|so)\b|\b(call|phone|fon)\s*kar(jo|so|vo)\b/.test(lower) || /(વાત કર|ફોન કર|કોલ કર|વાત કરવી)/.test(text) ||
  /(बात कर|बात करनी|बात करना|किसी से बात|इंसान से|பேச வேண்டும்|பேசணும்|மனிதர்|మాట్లాడాలి|మనిషి)/.test(text);
const humanWeak = /\b(human|person|agent|executive|representative|sales|associate|associative|staff|owner|manager|someone|call me|call back|callback|talk|speak|baat|vaat)\b/.test(lower) || /(વાત|ફોન|કોલ|માણસ)/.test(text) ||
  /(बात|इंसान|सेल्स|कॉल|फोन|मैनेजर|मालिक|एजेंट|किसी से|பேச|மனிதர்|கால்|போன்|அழைக்க|மேனேஜர்|మాట్లాడ|మనిషి|కాల్|ఫోన్|మేనేజర్)/.test(text);
const infoHi = /(માહિતી|મદદ|સમજ|પ્રશ્ન|કેવી રીતે|जानकारी|मदद|समझ|सवाल|डिटेल|बताइए|बताओ|क्या है|कैसे|உதவி|விவரம்|சந்தேகம்|புரியவில்லை|எப்படி|సహాయం|వివరాలు|సందేహం|అర్థం కాలేదు|ఎలా)/.test(text);
const infoStrong = /\b(more info|information|explain|query|question|doubt|confused|confusing|samajh|samjhao|samjav|samjao|jaankari|jankari|mahiti)\b|not understand|don'?t understand|didn'?t understand|\?/.test(lower) || infoHi;
const infoWeak = infoStrong || /\b(info|details|detail|help)\b/.test(lower);
const strictStep = stage === 'awaiting_details';
const wantsHuman = type === 'text' && (strictStep ? humanStrong : (humanStrong || humanWeak));
const wantsInfo = type === 'text' && (strictStep ? infoStrong : infoWeak);

// Amount parsing: ignores quantities ("20 pcs", "5 dozen"), takes the biggest money amount.
function parseAmount(s) {
  let t = String(s).replace(/[०-९]/g, d => String('०१२३४५६७८९'.indexOf(d))).toLowerCase();
  t = t.replace(/(\d),(?=\d)/g, '$1').replace(/(\d)([^\d\s.,\/-])/g, '$1 $2');
  const hasCurrency = /₹|\brs\b|\brs\.|\binr\b|rupee|रुपये|रुपए|रुपया|ரூ|రూ/.test(t);
  const QTY = /^(pcs|pieces|piece|pc|dozen|doz|dz|packets?|pkts?|box|boxes|sets?|nos|qty|gross|items?|units?)$/;
  const THOUSAND = /^(k|thousand|hazar|hazaar|हज़ार|हजार|ஆயிரம்|వేల|వెయ్యి)$/;
  const LAKH = /^(l|lakh|lakhs|lac|lacs|लाख|லட்சம்|లక్ష|లక్షలు)$/;
  const re = /(\d+(?:\.\d+)?)\s*(k|thousand|hazaar|hazar|हज़ार|हजार|ஆயிரம்|వేల|వెయ్యి|lakhs|lakh|lacs|lac|l|लाख|லட்சம்|లక్షలు|లక్ష|pcs|pieces|piece|pc|dozen|doz|dz|packets|packet|pkts|pkt|boxes|box|sets|set|nos|qty|gross|items|item|units|unit)?(?![a-z])/g;
  let best = null;
  let mm;
  while ((mm = re.exec(t)) !== null) {
    let n = parseFloat(mm[1]);
    const u = mm[2] || '';
    if (QTY.test(u)) continue;
    let moneyUnit = false;
    if (THOUSAND.test(u)) { n *= 1000; moneyUnit = true; }
    if (LAKH.test(u)) { n *= 100000; moneyUnit = true; }
    if (n > 50000000) continue;            // looks like a phone number, not an amount
    if (!(hasCurrency || moneyUnit || n >= 1000)) continue;
    if (best === null || n > best) best = n;
  }
  return best;
}

const rec = pickColumns(existing);
rec.phone = phone;
rec.whatsapp_name = m.contact_name || existing.whatsapp_name || '';
rec.first_contact = existing.first_contact || now;

let route = 'done';
let newStage = rawStage;
let alertTitle = '';
let ackKey = '';
let belowMoq = false;
let welcomeBack = false;
let quickStart = '';   // rate list sent before we know shop / business type: 'details' or 'type' = what to ask for next
let langChanged = false;

function startHandoff(reason) {
  route = 'handoff';
  alertTitle = reason;
  rec.paused_until = nowDt.plus({ hours: HANDOFF_PAUSE_HOURS }).toFormat(FMT);
  rec.last_alert_at = now;
}
function retryOrHandoff(retryRoute) {
  if (tries + 1 >= 2) {
    startHandoff('Confusing answers - the bot could not get a valid reply after 2 tries');
    newStage = stage;
  } else {
    route = retryRoute;
    newStage = stage + '#' + (tries + 1);
  }
}
function quietAlert(title) {
  if (canAlert) {
    route = 'alert_only';
    alertTitle = title;
    rec.last_alert_at = now;
  }
}

const MEDIA_LABEL = { image: 'a photo', video: 'a video', document: 'a document', audio: 'a voice note', voice: 'a voice note', location: 'a location', contacts: 'a contact card', order: 'a cart order' };
const afterCatalogue = ['awaiting_order_value', 'rate_list_sent', 'escalated_to_sales', 'order_received'].includes(stage);
const flowFinished = ['rate_list_sent', 'escalated_to_sales', 'order_received'].includes(stage);

// Orders placed on rajcreation.info arrive as a WhatsApp message starting with "🛒 NEW ORDER".
const isWebOrder = type === 'text' && /^\s*🛒\s*NEW ORDER/i.test(text);
let orderTotal = '';
let orderItems = '';

if (isWebOrder) {
  const grab = (re) => { const mm = text.match(re); return mm ? mm[1].trim() : ''; };
  orderTotal = grab(/TOTAL[^:\n]*:\s*(₹\s?[\d,]+(?:\.\d+)?)/); // capital TOTAL only, not "Items total"
  const webType = grab(/Business type:\s*(.+)/i);
  const webLevel = grab(/Price level:\s*(.+)/i);
  const webLang = ({ english: 'en', hindi: 'hi', gujarati: 'gu', tamil: 'ta', telugu: 'te' })[grab(/Language:\s*(\w+)/i).toLowerCase()];
  if (webLang && !pm) lang = webLang;
  const needsSales = /NEEDS SALES ASSOCIATE/i.test(text);
  const typeClash = webType && rec.category && typeOf(webType) !== typeOf(rec.category);
  const packets = grab(/Packets[^:\n]*:\s*(\d+)/i);
  const shop = grab(/Name \/ Shop:\s*(.+)/i).replace(/^-$/, '');
  const city = grab(/City:\s*(.+)/i).replace(/^-$/, '');
  orderItems = text.split('\n').map((l) => l.trim()).filter((l) => /^\d+\)/.test(l))
    .map((l) => { const pk = l.match(/(\d+) (pkt|box)\b/); return l.replace(/^\d+\)\s*/, '').split(' – ')[0] + (pk ? ' ×' + pk[1] + ' ' + pk[2] : ''); })
    .join(', ');
  route = 'web_order';
  ackKey = 'order_ack';
  newStage = 'order_received';
  rec.order_value = orderTotal ? orderTotal + ' incl. GST (website order)' : 'Website order';
  if (needsSales) ackKey = 'order_ack_sales';
  rec.interested_items = appendItems(rec.interested_items, 'WEB ORDER ' + now + ': ' + orderItems);
  if (!rec.business_details && (shop || city)) rec.business_details = [shop, city].filter(Boolean).join(', ');
  if (!rec.category && webType) rec.category = webType;
  rec.paused_until = nowDt.plus({ hours: HANDOFF_PAUSE_HOURS }).toFormat(FMT);
  rec.last_alert_at = now;
  alertTitle = (needsSales ? 'WEBSITE ORDER – NEEDS YOUR CALL (cartons) ' : 'New WEBSITE ORDER ') + (orderTotal || '') + ' incl. GST' +
    (packets ? ' (' + packets + ' packets / boxes)' : '') + (webType ? ', ' + webType : '') + (webLevel && webLevel !== webType ? ' at ' + webLevel + ' prices' : '') +
    (typeClash ? ' – NOTE: told the bot "' + rec.category + '"' : '') + ' – please confirm stock, colours and shipping with the customer.';
} else if (type === 'sticker') {
  route = 'done';
} else if (MEDIA_LABEL[type]) {
  if (type === 'image') rec.order_photo = 'Yes - ' + now;
  if (text) rec.interested_items = appendItems(rec.interested_items, text);
  if (canAlert) {
    route = 'media';
    ackKey = type === 'image' ? 'photo_ack' : 'media_ack';
    alertTitle = 'Customer sent ' + MEDIA_LABEL[type] + (isPaused ? ' (bot is paused for them)' : '') + '. Please check their chat.';
    rec.last_alert_at = now;
  }
} else if (isPaused) {
  if (wantsCatalogue && stage && stage !== 'awaiting_language') {
    route = 'resend_catalogue';
  } else if (!isFiller) {
    rec.interested_items = appendItems(rec.interested_items, text);
    quietAlert('New message from a customer you are handling (the bot is staying quiet for them).');
  }
} else if (!stage) {
  // Any first message starts the chat. A price / item / catalogue question gets the rate list right away
  // (opened on those items) and we ask for the shop name in the same message. Hindi / Tamil / Telugu script: that language.
  if (type === 'text' && !isGreeting && !isFiller) rec.interested_items = appendItems(rec.interested_items, 'First message: ' + text);
  if (itemAsk && !humanStrong) { lang = scriptLang || 'en'; route = 'resend_rates'; quickStart = 'details'; newStage = 'awaiting_details'; }
  else if (scriptLang) { lang = scriptLang; route = 'greet'; newStage = 'awaiting_details'; }
  else { route = 'ask_language'; newStage = 'awaiting_language'; }
} else if (stage === 'awaiting_language') {
  const l = text.toLowerCase();
  if (itemAsk && !replyId && !humanStrong) {
    // asked about items instead of picking a language: answer, and carry on in English (or the script they wrote in)
    rec.interested_items = appendItems(rec.interested_items, text);
    lang = scriptLang || (typedLang ? LANG_WORDS[typedLang] : 'en'); route = 'resend_rates'; quickStart = 'details'; newStage = 'awaiting_details';
  }
  // typed instead of tapped, with typos: "hindhi", "englis", "tamizh", "telgu" – or written in that script
  else if (!replyId && (typedLang || scriptLang)) { lang = typedLang ? LANG_WORDS[typedLang] : scriptLang; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_gu' || /gujarati|gujrati|ગુજરાતી/.test(l)) { lang = 'gu'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_hi' || /hindi|हिंदी|हिन्दी/.test(l)) { lang = 'hi'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_ta' || /tamil|தமிழ்/.test(l)) { lang = 'ta'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_te' || /telugu|తెలుగు/.test(l)) { lang = 'te'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (replyId === 'lang_en' || /english|इंग्लिश|अंग्रेज़ी|अंग्रेजी/.test(l)) { lang = 'en'; route = 'greet'; newStage = 'awaiting_details'; }
  else if (humanStrong) startHandoff('Asked to speak to a sales associate / human');
  else if (isGreeting && tries < 1) retryOrHandoff('ask_language'); // a second "hi": show the language list once more
  else { lang = 'en'; route = 'greet'; newStage = 'awaiting_details'; } // anything else: carry on in English
} else if (langPick) {
  // changed language later (tapped an old language list, or typed "Hindi"): switch and repeat the current step
  lang = langPick; langChanged = true;
  if (stage === 'awaiting_details') route = 'greet';
  else if (stage === 'awaiting_category') route = 'ask_category';
  else if (afterCatalogue) route = 'resend_rates';
  else route = 'greet';
} else if (typedOrder && afterCatalogue && !humanStrong) {
  // an order typed in the chat: rate list opened on those items so they can send it properly, and Mahek is told
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
  alertTitle = 'Customer typed an order in the chat (' + askCodes.join(', ') + '). The bot sent the rate list with these items – please check.';
  rec.last_alert_at = now;
} else if (type === 'interactive' && TYPE_IDS[replyId] && afterCatalogue) {
  // Tapped the business-type list again later: switch the type and resend the rate list link.
  rec.category = TYPE_NAMES[TYPE_IDS[replyId]];
  route = 'resend_rates';
  newStage = 'rate_list_sent';
} else if (afterCatalogue && !humanStrong && (priceAsk || askCodes.length)) {
  // "item 345 price?", "hair bows rate?" after the rate list: send the rate list link again (opened on that item)
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
} else if (afterCatalogue && !humanStrong && !availAsk && (catalogueAsk || productAsk)) {
  // "scrunchies designs?", "catlog" – send the catalogue links again
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_catalogue';
} else if (((stage === 'awaiting_details' && detailsAsk) || (stage === 'awaiting_category' && !categoryHit && itemAsk)) && !humanStrong) {
  // A price / item question while we wait for the shop name / business type: send the rate list now, and ask again in the same message.
  rec.interested_items = appendItems(rec.interested_items, text);
  route = 'resend_rates';
  quickStart = stage === 'awaiting_details' ? 'details' : 'type';
} else if ((stage === 'awaiting_details' || (stage === 'awaiting_category' && !categoryHit)) && type === 'text' && !humanStrong &&
    (availAsk || /\?/.test(text))) {
  // Another question while we wait: note it and ask again.
  rec.interested_items = appendItems(rec.interested_items, text);
  retryOrHandoff(stage === 'awaiting_details' ? 'details_retry' : 'ask_category');
} else if (afterCatalogue && wantsCatalogue) {
  route = 'resend_catalogue';
} else if (stage === 'rate_list_sent' && wantsRates) {
  route = 'resend_rates';
} else if (flowFinished && isGreeting) {
  // returning customer says hi: welcome them back with their rate list button instead of starting over
  route = 'resend_rates';
  welcomeBack = true;
} else if (wantsHuman) {
  if (afterCatalogue) rec.interested_items = appendItems(rec.interested_items, text);
  startHandoff('Asked to speak to a sales associate / human');
} else if (stage !== 'escalated_to_sales' && wantsInfo && !(stage === 'awaiting_category' && categoryHit)) {
  if (afterCatalogue) rec.interested_items = appendItems(rec.interested_items, text);
  startHandoff('Needs more information');
} else if (stage === 'awaiting_details') {
  const fillers = ['hi', 'hii', 'hiii', 'hello', 'helo', 'hey', 'namaste', 'ok', 'okay', 'k', 'yes', 'no', 'thanks', 'thank you', 'thankyou', 'good morning', 'good afternoon', 'good evening', 'catalogue', 'catalog', 'price', 'rate', 'rates'];
  const c2 = lower.replace(/[^a-zऀ-ॿ઀-૿஀-௿ఀ-౿ ]/g, '').trim();
  const valid = type === 'text' && c2.length >= 3 && !fillers.includes(c2) && !FILLERS.includes(c2);
  if (valid) {
    route = 'ask_category';
    rec.business_details = text;
    newStage = 'awaiting_category';
  } else {
    retryOrHandoff('details_retry');
  }
} else if (stage === 'awaiting_category') {
  // List ids, or a typed answer matched by keyword. Old list ids (shopkeeper, new_business) still work.
  const hit = categoryHit;
  if (hit || type === 'interactive') {
    // Catalogue links + rate list link go out together; no order-value question any more.
    route = 'send_catalogue';
    rec.category = hit ? TYPE_NAMES[hit] : (text || 'Other / Home seller');
    newStage = 'rate_list_sent';
  } else {
    retryOrHandoff('ask_category');
  }
} else if (stage === 'awaiting_order_value') {
  const lowSel = replyId === 'ov_low' || /less than|से कम|கீழ்|కంటే తక్కువ/i.test(text);
  const highSel = replyId === 'ov_high' || /or more|या अधिक|से ज़्यादा|से ज्यादा|அல்லது மேல்|లేదా ఎక్కువ/i.test(text);
  const typed = (lowSel || highSel) ? null : parseAmount(text);
  const amt = highSel ? BIG_ORDER : (lowSel ? 0 : typed);
  if (amt === null) {
    rec.interested_items = appendItems(rec.interested_items, text);
    retryOrHandoff('order_retry');
  } else if (amt < BIG_ORDER) {
    route = 'order_low';
    rec.order_value = lowSel ? 'Less than ₹10,000' : inr(amt);
    belowMoq = !lowSel && amt < MOQ;
    newStage = 'rate_list_sent';
  } else {
    route = 'order_high';
    rec.order_value = highSel ? '₹10,000 or more' : inr(amt);
    newStage = 'escalated_to_sales';
    alertTitle = 'Big order (₹10,000 or more). Please contact this customer.';
    rec.last_alert_at = now;
    rec.paused_until = nowDt.plus({ hours: HANDOFF_PAUSE_HOURS }).toFormat(FMT);
  }
} else if (!isFiller) {
  rec.interested_items = appendItems(rec.interested_items, text);
  if (stage === 'rate_list_sent') startHandoff('Sent items / follow-up after receiving the rate list');
  else if (stage === 'escalated_to_sales') startHandoff('Follow-up message after a big-order request');
  else if (stage === 'order_received') startHandoff('Follow-up message after a website order');
  else startHandoff('Sent a message the bot could not handle');
}

