function cityName(x) {
  const k = String(x || '').toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
  if (k.length < 3) return '';
  return CITIES.find((c) => c.toLowerCase() === k) || CITIES.find((c) => near(k, c.toLowerCase())) || '';
}
// "Sharma Fancy Store, Pune", "1️⃣ Sharma Fancy Store\n2️⃣ Pune", "Sharma store pune", "Sharma Store from Pune",
// "Shop: Sharma Store City: Pune" -> shop + city, so the website order form is pre-filled.
function splitDetails(s) {
  s = String(s || '').replace(/\s+(?:city|town|shaher|shahar|sheher)\s*[:-]\s*/i, '\n');
  let parts = s.split(/[\n,]+/)
    .map((p) => p.replace(/^\s*(?:\d️?⃣|\d{1,2}\s*[.)])\s*/, '').replace(/^(?:shop name|business name|shop|business|name|city)\s*[:-]\s*/i, '').trim())
    .filter(Boolean);
  if (parts.length === 1) {
    const one = parts[0], ws = one.split(/\s+/);
    const m = one.match(/^(.*\S)\s+(?:from|frm|in|at|se|thi|-|–|\/)\s+(\S.*)$/i);
    if (m && m[1].length >= 2 && m[2].split(/\s+/).length <= 3) parts = [m[1], m[2]];
    else for (const n of [2, 1]) {
      const city = ws.length > n ? cityName(ws.slice(-n).join(' ')) : '';
      if (city) { parts = [ws.slice(0, -n).join(' '), city]; break; }
    }
  }
  if (!parts.length) return { shop: '', city: '' };
  if (parts.length === 1) return { shop: parts[0].slice(0, 60), city: '' };
  const last = parts[parts.length - 1];
  return { shop: parts.slice(0, -1).join(', ').slice(0, 60), city: (cityName(last) || last).slice(0, 40) };
}
